package com.bank.empevent;

import java.util.*;
import java.util.function.Consumer;
import java.util.logging.*;

public class ConsumerAndThenDemo {
    private static final Logger log = Logger.getLogger("EmpEvent");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> newHires = List.of(new Employee("Rajesh"), new Employee("Priya"));
        EmployeeEventService service = new EmployeeEventService(log);

        service.onboardAll(newHires);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    Employee(String name) { this.name = name; }
    String getName() { return name; }
}

// ─── Would be in service/EmployeeEventService.java ───
class EmployeeEventService {
    private final Logger log;
    EmployeeEventService(Logger log) { this.log = log; }

    void onboardAll(List<Employee> hires) {
        Consumer<Employee> audit  = e -> log.info(() -> "AUDIT: onboarded " + e.getName());
        Consumer<Employee> notify = e -> log.info(() -> "NOTIFY: welcome " + e.getName());
        Consumer<Employee> both = audit.andThen(notify);   // audit THEN notify

        hires.forEach(both);
    }
}
